import{_ as t,o,c as e,ag as l}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"我执","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-我执.md","filePath":"50-概念资料/dict-我执.md","lastUpdated":1778031108000}'),i={name:"50-概念资料/dict-我执.md"};function u(r,a,q,d,h,c){return o(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="我执" tabindex="-1">我执 <a class="header-anchor" href="#我执" aria-label="Permalink to &quot;我执&quot;">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>我执是对&quot;自我&quot;的执着——认为有一个永恒不变的&quot;我&quot;，并以此为一切判断的出发点。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;若菩萨有我相、人相、众生相、寿者相，即非菩萨。&quot;</p></blockquote><blockquote><p>&quot;太在意别人的评价，是因为还有&#39;我相&#39;——我在别人心中是什么形象？放下这个&#39;我&#39;，就没有人需要评价我了。&quot;</p></blockquote><blockquote><p>&quot;忍辱不是憋着，是看破、放下。被人骂的时候试着用旁观者的心态——&#39;他为什么这么激动？&#39;而不是&#39;他在骂我！&#39;&quot;</p></blockquote><h2 id="我执的表现" tabindex="-1">我执的表现 <a class="header-anchor" href="#我执的表现" aria-label="Permalink to &quot;我执的表现&quot;">​</a></h2><ul><li>被批评时立刻反驳</li><li>过度在意别人的看法</li><li>凡事以&quot;我&quot;为中心判断利弊</li><li>把&quot;我的观点&quot;等同于真理</li></ul><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-法执">法执</a> — 我执的延伸</li><li><a href="/50-概念资料/dict-无明">无明</a> — 我执的根源</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/model-对境不住">对境不住</a> — 不被&quot;我相&quot;带跑</li><li><a href="/model-对法不执">对法不执</a> — 放下对&quot;我&quot;和&quot;我的&quot;的执着</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>每次想说&quot;我&quot;的时候，试着站在第三方角度</li><li>被批评时先听对方说完，不急着反驳</li><li>观察&quot;我在生气&quot;而不是&quot;我很生气&quot;</li></ul>',15)])])}const _=t(i,[["render",u]]);export{s as __pageData,_ as default};
